// Drive the status from your own mutation instead of the promise:
<DialogConfirmTyped status={mutation.status === "pending" ? "pending" : mutation.isError ? "error" : "idle"} onConfirm={(name) => mutation.mutate(name)} />

<DialogConfirmTyped tone="neutral" requireTyping={false} alternative={false} triggerLabel="Remove member" title="Remove {name}" />

